#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());
    int count = 0;
    for (int i = 0; i + 2 < n; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        int l = i + 1, rr = n - 1;
        while (l < rr) {
            long long t = a[i] + a[l] + a[rr];
            if (t < 0) l++;
            else if (t > 0) rr--;
            else {
                count++;
                l++;
                rr--;
                while (l < rr && a[l] == a[l - 1]) l++;
            }
        }
    }
    cout << count << "\n";

    return 0;
}

