        long n = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();

        Arrays.sort(a);
        int count = 0;
        for (int i = 0; i + 2 < n; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue;
            int l = i + 1, rr = (int) n - 1;
            while (l < rr) {
                long t = a[i] + a[l] + a[rr];
                if (t < 0) l++;
                else if (t > 0) rr--;
                else {
                    count++;
                    l++;
                    rr--;
                    while (l < rr && a[l] == a[l - 1]) l++;
                }
            }
        }
        System.out.println(count);
